-- Compactación de adjuntos repetidos de Conversaciones (ConversacionesAdjuntosCompactacionHostedService).
-- Idempotente: agrega las claves solo si no existen y no cambia valores ya cargados.
SET NOCOUNT ON;
IF OBJECT_ID(N'dbo.TA_CONFIGURACION',N'U') IS NULL RETURN;
IF NOT EXISTS(SELECT 1 FROM dbo.TA_CONFIGURACION WHERE CLAVE=N'CONVERSACIONES-ADJUNTOS-COMPACTAR')
    INSERT dbo.TA_CONFIGURACION(GRUPO,CLAVE,VALOR,DESCRIPCION) VALUES(N'CONVERSACIONES',N'CONVERSACIONES-ADJUNTOS-COMPACTAR',N'SI',N'Deja una sola copia de cada adjunto repetido, en disco y en la base (SI/NO)');
IF NOT EXISTS(SELECT 1 FROM dbo.TA_CONFIGURACION WHERE CLAVE=N'CONVERSACIONES-ADJUNTOS-COMPACTAR-LOTE')
    INSERT dbo.TA_CONFIGURACION(GRUPO,CLAVE,VALOR,DESCRIPCION) VALUES(N'CONVERSACIONES',N'CONVERSACIONES-ADJUNTOS-COMPACTAR-LOTE',N'50',N'Adjuntos revisados por pasada de la compactación (1 a 500)');
IF NOT EXISTS(SELECT 1 FROM dbo.TA_CONFIGURACION WHERE CLAVE=N'CONVERSACIONES-ADJUNTOS-BORRAR-HUERFANOS')
    INSERT dbo.TA_CONFIGURACION(GRUPO,CLAVE,VALOR,DESCRIPCION) VALUES(N'CONVERSACIONES',N'CONVERSACIONES-ADJUNTOS-BORRAR-HUERFANOS',N'NO',N'Borra archivos de adjuntos que ninguna conversación usa (SI/NO; primero se informan)');
